//! Deterministic demo fixtures delivered through the same import pipeline the
//! real data uses. Everything is generated byte-for-byte reproducibly.

use std::collections::BTreeMap;

use crate::coding::{encode, CodingParams};
use crate::gf::Gf256;
use crate::importer::write_bundle;
use crate::model::{sha256_hex, Manifest};
use std::path::Path;

fn object_payload(label: &[u8], len: usize) -> Vec<u8> {
    let mut out = Vec::with_capacity(len);
    let mut state = 0x9e37_79b9u32 ^ label.first().copied().unwrap_or(0) as u32;
    while out.len() < len {
        state ^= state << 13;
        state ^= state >> 17;
        state ^= state << 5;
        out.push((state & 0xff) as u8);
    }
    out
}

struct BuiltObject {
    manifest: Manifest,
    /// shards[stripe][index] = bytes
    shards: Vec<Vec<Vec<u8>>>,
}

fn build_object(
    object_id: &str,
    k: usize,
    m: usize,
    stripe_count: usize,
    shard_len: usize,
    data_len: usize,
    generation: u64,
) -> BuiltObject {
    let gf = Gf256::new();
    let params = CodingParams { version: 1, k, n: k + m, shard_len };
    let payload = object_payload(object_id.as_bytes(), data_len);
    let mut shards = Vec::new();
    for stripe in 0..stripe_count {
        let mut data = Vec::with_capacity(k);
        for d in 0..k {
            let start = (stripe * k + d) * shard_len;
            let mut piece = vec![0u8; shard_len];
            for (i, b) in piece.iter_mut().enumerate() {
                if start + i < payload.len() {
                    *b = payload[start + i];
                }
            }
            data.push(piece);
        }
        shards.push(encode(&gf, params, &data));
    }
    let manifest = Manifest {
        scheme: crate::coding::CODING_SCHEME.into(),
        version: 1,
        object_id: object_id.into(),
        object_digest_hex: sha256_hex(&payload),
        stripe_count,
        shard_len,
        data_shards: k,
        parity_shards: m,
        generation,
        data_len,
    };
    BuiltObject { manifest, shards }
}

/// Populate `incoming/` with a reproducible, messy delivery scenario.
/// Returns the list of object ids created.
pub fn seed_demo(incoming: &Path) -> anyhow::Result<Vec<String>> {
    if incoming.exists()
        && std::fs::read_dir(incoming)?.next().is_some()
    {
        return Ok(vec![]);
    }
    std::fs::create_dir_all(incoming)?;

    // Object A: k=3 n=5, 3 stripes. Demonstrates:
    //  - bit flips excluded by sidecar digest
    //  - repeated shard numbers (identical redelivery + distinct content candidates)
    //  - generation mixing on stripe 2
    //  - recovery at the k=3 floor
    let a = build_object("obj-alpha", 3, 2, 3, 8, 3 * 3 * 8, 7);
    let mut sidecars_a: BTreeMap<(usize, usize, u64), String> = BTreeMap::new();
    let digest = |b: &[u8]| sha256_hex(b);
    for s in 0..3 {
        for i in 0..5 {
            sidecars_a.insert((s, i, 7), digest(&a.shards[s][i]));
        }
    }
    // Source "alpha-node-0": data 0,1,2 stripe 0; parity 3 stripe 1.
    let a0: Vec<(usize, usize, u64, Vec<u8>)> = vec![
        (0, 0, 7, a.shards[0][0].clone()),
        (0, 2, 7, a.shards[0][2].clone()),
        (1, 3, 7, a.shards[1][3].clone()),
    ];
    write_bundle(incoming, "alpha-node-0", &a.manifest, &a0, &sidecars_a)?;

    // Bit-flipped copy of stripe0/shard1 with a FORGED matching sidecar:
    // the per-shard digest check passes, but reconstruction from any combo
    // containing it fails cross-validation against the clean parity shards,
    // so it is recorded as corroboration_failed corruption evidence.
    let mut flipped = a.shards[0][1].clone();
    flipped[0] ^= 0x01;

    // Source "alpha-node-1": stripe0 parity 3,4 (so stripe0 recovers at k=3
    // floor using 0,1,2 from node-0 after the flipped copy is excluded).
    let a1: Vec<(usize, usize, u64, Vec<u8>)> = vec![
        // identical redelivery of s0 i0: duplicate index, same content
        (0, 0, 7, a.shards[0][0].clone()),
        (0, 3, 7, a.shards[0][3].clone()),
        (0, 4, 7, a.shards[0][4].clone()),
        // stripe 1: data 0,1 (parity 3 from node-0 is bit-rot-free)
        (1, 0, 7, a.shards[1][0].clone()),
        (1, 1, 7, a.shards[1][1].clone()),
        // stripe 2: gen7 data 2 (gen8 partial write on node-2 leaves only i0
        // at gen8, so generation mixing must be resolved in favour of gen7)
        (2, 2, 7, a.shards[2][2].clone()),
    ];
    write_bundle(incoming, "alpha-node-1", &a.manifest, &a1, &sidecars_a)?;

    // The flipped s0 i1 goes to node-2, original digest sidecar preserved.
    let a2: Vec<(usize, usize, u64, Vec<u8>)> = vec![
        (0, 1, 7, flipped.clone()),
        (1, 2, 7, a.shards[1][2].clone()),
        (1, 4, 7, a.shards[1][4].clone()),
        // stripe 2 generation mixing: node-2 partially wrote generation 8
        (2, 0, 8, a.shards[2][0].clone()),
        (2, 1, 7, a.shards[2][1].clone()),
        (2, 2, 7, a.shards[2][2].clone()),
        (2, 3, 7, a.shards[2][3].clone()),
        (2, 4, 7, a.shards[2][4].clone()),
    ];
    let mut side_a2 = sidecars_a.clone();
    // FORGED sidecar matches the flipped bytes -> passes digest gate.
    side_a2.insert((0, 1, 7), digest(&flipped));
    side_a2.insert((2, 0, 8), digest(&a.shards[2][0]));
    write_bundle(incoming, "alpha-node-2", &a.manifest, &a2, &side_a2)?;

    // node-3: stripe 2 carries a wrong-length shard and a second content
    // candidate for index 1 (same generation, different bytes).
    let mut too_short = a.shards[2][2].clone();
    too_short.pop();
    let mut bogus_i1 = a.shards[2][1].clone();
    bogus_i1[3] ^= 0x5a;
    let a3: Vec<(usize, usize, u64, Vec<u8>)> = vec![
        (2, 1, 7, bogus_i1.clone()),
        (2, 2, 7, too_short),
        // stripe 1 extra data 2 duplicate (identical)
        (1, 2, 7, a.shards[1][2].clone()),
    ];
    // No sidecar for the bogus candidate: missing-sidecar also excludes it.
    let mut side_a3 = sidecars_a.clone();
    side_a3.insert((2, 1, 7), digest(&bogus_i1));
    side_a3.remove(&(2, 2, 7));
    write_bundle(incoming, "alpha-node-3", &a.manifest, &a3, &side_a3)?;

    // Object B: k=1 n=3 single stripe — recovery at the absolute floor and a
    // manifest disagreement from one source.
    let b = build_object("obj-beta", 1, 2, 1, 6, 6, 1);
    let side_b: BTreeMap<(usize, usize, u64), String> =
        (0..3).map(|i| ((0, i, 1), digest(&b.shards[0][i]))).collect();
    let b0: Vec<(usize, usize, u64, Vec<u8>)> = vec![
        (0, 0, 1, b.shards[0][0].clone()),
        (0, 1, 1, b.shards[0][1].clone()),
    ];
    write_bundle(incoming, "beta-node-0", &b.manifest, &b0, &side_b)?;
    let b1: Vec<(usize, usize, u64, Vec<u8>)> =
        vec![(0, 2, 1, b.shards[0][2].clone())];
    write_bundle(incoming, "beta-node-1", &b.manifest, &b1, &side_b)?;

    Ok(vec!["obj-alpha".into(), "obj-beta".into()])
}
